assert.equal(normalizeSetCode('PTDNIT004').code,'PTDN-IT004');
assert.equal(normalizeSetCode('SDDLIT007').code,'SDDL-IT007');
assert(setCodeCandidates('YS13-1T002').some(item=>item.code==='YS13-IT002'),'I/1 nella regione non genera il candidato strutturale');
assert(setCodeCandidates('BP02TT044').some(item=>item.code==='BP02-IT044'),'IT/TT senza trattino non genera il candidato strutturale');
assert(setCodeCandidates('BP02-11044').some(item=>item.code==='BP02-IT044'&&item.structural&&item.edits===2),'IT/11 non genera una correzione strutturale controllata');
assert.equal(normalizeSetCode('rumore\nTDGS-IT001\naltro').code,'TDGS-IT001','estrae il codice senza fondere il rumore OCR');
for(const raw of ['18 LVAL-IT051','LVAL-IT051.','XX LVAL-IT051 7','| LVAL-IT051 |'])assert.deepEqual(extractSetCodeCandidates(raw),['LVAL-IT051'],`rumore OCR non rimosso: ${raw}`);
assert(setCodeCandidates('ABCD-IT001 / LVAL-IT051').some(item=>item.code==='LVAL-IT051'&&!item.corrected),'ogni candidato OCR plausibile deve arrivare all’exact lookup');
assert.equal(normalizeSetCode('LOB-001').valid,true);
assert.equal(normalizeSetCode('L5DD-ENY39').valid,true);
assert.equal(normalizeSetCode('JUSH-IT047').valid,true);
assert.equal(normalizeSetCode('L5DD-ENC32').valid,true);
for(const code of ['SDM-I105','TDGS-EN004','L26D-ENS26'])assert.deepEqual(normalizeSetCode(code),{raw:code,code,valid:true},`codice lungo/storico non preservato: ${code}`);
assert.deepEqual(normalizeSetCode(' L26D–ENX40 '),{raw:' L26D–ENX40 ',code:'L26D-ENX40',valid:true});
assert.equal(normalizeSetCode('codice?').valid,false);
assert(setCodeCandidates('TDGS-ITO01').some(item=>item.code==='TDGS-IT001'&&item.ambiguous),'O/0 produce candidato, non correzione silenziosa');
assert.equal(setCodeCandidates('PHNI-ITO46')[1].code,'PHNI-IT046','lo zero nel suffisso numerico deve avere prioritÃ ');
assert(setCodeCandidates('PHNI-ITOO6').some(item=>item.code==='PHNI-IT006'),'piÃ¹ O nel suffisso numerico non vengono convertite in 0');
assert(setCodeCandidates('OCRBR-ITO14').some(item=>item.code==='CRBR-IT014'),'carattere spurio iniziale e O/0 non vengono corretti insieme');
assert(setCodeCandidates('TG-ZDEJ7').some(item=>item.code==='TG-2DEJ7'),'Z/2 produce soltanto una variante esplicita');
assert(setCodeCandidates('L26D-ENX4O').some(item=>item.code==='L26D-ENX40'),'O/0 supportato sul nuovo formato');
assert(setCodeCandidates('L5DD-ENY3S').some(item=>item.code==='L5DD-ENY35'),'S/5 produce un candidato conservativo');
assert.equal(classifyPrintingMatch({normalized:normalizeSetCode('LOB-001'),matches:[{id:1}],consensus:2}).decision,SCAN_DECISION.EXACT_UNIQUE);
assert.equal(classifyPrintingMatch({normalized:normalizeSetCode('LOB-001'),matches:[{id:1}],ocrConfidence:62}).status,'high_confidence','exact unique deve ignorare la confidence Paddle');
assert.equal(classifyPrintingMatch({normalized:normalizeSetCode('LOB-001'),matches:[{id:1},{id:2}]}).decision,SCAN_DECISION.AMBIGUOUS);
assert.equal(classifyPrintingMatch({normalized:normalizeSetCode('LOB-001'),matches:[]}).status,'not_found');
assert.equal(classifyPrintingMatch({normalized:normalizeSetCode('TG-ZDEJ7'),matches:[],consensus:3}).status,'not_found','codice plausibile ma inesistente scartato');
assert.equal(classifyNearPrintingMatch([{candidate:{code:'LVAL-IT051',edits:1},matches:[{printingId:'p'}]}]).decision,SCAN_DECISION.NEAR_UNIQUE);
assert.equal(classifyNearPrintingMatch([{candidate:{code:'LVAL-IT051',edits:2},matches:[{printingId:'p'}]}]).decision,SCAN_DECISION.AMBIGUOUS);
assert.equal(classifyNearPrintingMatch([{candidate:{code:'LVAL-IT051',edits:1},matches:[{printingId:'p'}]}],{plausibleCandidateCount:2}).decision,SCAN_DECISION.AMBIGUOUS,'due candidati OCR plausibili non possono essere auto-accettati');

const consensus=new OcrConsensus();
assert.equal(consensus.observe('L26D-ENX40',74).ready,false);
const converged=consensus.observe('L26D-ENX40',78);assert.equal(converged.ready,true);assert.equal(converged.code,'L26D-ENX40');assert.equal(converged.votes,2);
const noisyConsensus=new OcrConsensus();noisyConsensus.observe('L26D-ENX4O',71);noisyConsensus.observe('L26D-ENX40',76);const reconciled=noisyConsensus.observe('L26D-ENX40',79);assert.equal(reconciled.ready,true);assert.equal(reconciled.code,'L26D-ENX40','2 letture su 3 convergono senza correzione silenziosa');

const still=new Array(128).fill(80), changed=new Array(128).fill(230); const gate=new ScanGate({sameCodeCooldown:1000});
assert.equal(signatureDistance(still,still),0,'frame stabile deve avere distanza zero');assert(signatureDistance(still,changed)>.065,'un frame in movimento deve superare la soglia OCR');
assert(gate.consider('LOB-001',still,0));
assert.equal(gate.consider('LOB-001',still,1500),false,'stessa carta ferma non duplicata anche dopo cooldown');
gate.miss();gate.miss();assert(gate.consider('LOB-001',still,1600),'uscita dal frame riabilita la stessa printing');
assert(gate.consider('LOB-001',changed,3000),'variazione frame permette copia consecutiva');

