{const width=48,height=16,data=new Uint8ClampedArray(width*height*4).fill(128);for(let p=0;p<width*height;p++)data[p*4+3]=255;const stats=preprocessCodeImage({getImageData:()=>({data}),putImageData:()=>{}},width,height,{mode:'grayscale'});assert(stats.sharpness<3,'una ROI piatta/sfocata deve essere rilevata come poco nitida');}

